import React from 'react';

const DashboardChart = ({ data, title }) => {
  if (!data || data.length === 0) {
    return <div className="text-center text-muted p-4">لا توجد بيانات كافية للرسم البياني.</div>;
  }

  const maxValue = Math.max(...data.map(d => d.value));
  const chartHeight = 250;
  const barWidth = 40;
  const barMargin = 20;
  const chartWidth = data.length * (barWidth + barMargin);

  return (
    <div className="card shadow-sm">
      <div className="card-header bg-light fw-bold">{title}</div>
      <div className="card-body" style={{ overflowX: 'auto' }}>
        <svg width={chartWidth} height={chartHeight} className="d-block mx-auto">
          <g className="chart-grid">
            {[...Array(5)].map((_, i) => (
              <line
                key={i}
                x1="0"
                y1={(chartHeight - 30) / 4 * i + 10}
                x2={chartWidth}
                y2={(chartHeight - 30) / 4 * i + 10}
                stroke="#e0e0e0"
                strokeDasharray="3,3"
              />
            ))}
          </g>
          {data.map((d, i) => {
            const barHeight = maxValue > 0 ? (d.value / maxValue) * (chartHeight - 50) : 0;
            const x = i * (barWidth + barMargin) + barMargin / 2;
            const y = chartHeight - barHeight - 20;
            return (
              <g key={d.label} className="chart-bar">
                <title>{`${d.label}: ${d.value}`}</title>
                <rect
                  x={x}
                  y={y}
                  width={barWidth}
                  height={barHeight}
                  fill="var(--bs-primary)"
                  rx="4"
                />
                <text x={x + barWidth / 2} y={chartHeight - 5} textAnchor="middle" fontSize="12" fill="var(--text-main)">
                  {d.label}
                </text>
                 <text x={x + barWidth / 2} y={y - 5} textAnchor="middle" fontSize="14" fontWeight="bold" fill="var(--text-main)">
                  {d.value}
                </text>
              </g>
            );
          })}
        </svg>
      </div>
    </div>
  );
};

export default DashboardChart;
